// Shared types for the "AI commands" fork feature. Used by the main process
// (config + local API + LLM calls), the preload IPC shim, and the composer UI.

export type AiCommandLevels = Readonly<{
  /** Number of levels, e.g. 10 → levels 1..10. */
  count: number;
  /** Level preselected in the picker. */
  default: number;
  /**
   * When true, the per-level descriptions are generated by the model from the
   * recent conversation (and cached per conversation), so the scale "evolves"
   * with the chat. When false a generic scale is shown.
   */
  evolving: boolean;
  /** What the level controls, in words ("how brutal the insult is"). */
  describe: string;
}>;

/** What the renderer needs to know about a command. Never carries secrets. */
export type AiCommandSummary = Readonly<{
  id: string;
  label: string;
  /** Axo symbol name for the pinned button (defaults to `bolt`). */
  symbol: string | null;
  /** Pinned commands render as their own button next to the mic. */
  pinned: boolean;
  levels: AiCommandLevels | null;
  /** Submit the generated text immediately instead of leaving it as a draft. */
  autoSend: boolean;
}>;

export type AiLevelDescriptor = Readonly<{
  level: number;
  title: string;
  description: string;
}>;

export type AiLevelScale = Readonly<{
  commandId: string;
  conversationId: string;
  levels: ReadonlyArray<AiLevelDescriptor>;
  generatedAt: number;
  source: 'model' | 'fallback';
}>;

export type AiRunResult =
  | Readonly<{ ok: true; text: string; durationMs: number }>
  | Readonly<{ ok: false; error: string }>;

/** Config slice handed to the renderer. */
export type AiCommandsClientConfig = Readonly<{
  enabled: boolean;
  providerLabel: string;
  configPath: string;
  commands: ReadonlyArray<AiCommandSummary>;
}>;

/** Pushed from the main process (local API `POST /v1/compose`) to the UI. */
export type AiComposeRequest = Readonly<{
  conversationId: string;
  text: string;
  send: boolean;
}>;

export const AI_IPC = {
  getClientConfig: 'ai-commands:get-client-config',
  getLevelScale: 'ai-commands:get-level-scale',
  run: 'ai-commands:run',
  openConfig: 'ai-commands:open-config',
  setActiveConversation: 'ai-commands:set-active-conversation',
  // main → renderer
  configChanged: 'ai-commands:config-changed',
  compose: 'ai-commands:compose',
} as const;
